const stepTitles = ['Open the right record', 'Verify the starting information', 'Complete the main action', 'Review the result', 'Finish and document']

function finalLesson({ id, title, summary, product, course, features = [], permissions = [], keywords = [], workflow, screen }) {
  return {
    id, title, summary, product, course, features, permissions, keywords,
    steps: workflow.map((body, index) => [stepTitles[index], body]),
    success: screen.success,
    safety: screen.safety,
    screen: {
      kind: screen.kind,
      nav: screen.nav,
      page: screen.page,
      state: screen.state,
      fields: [
        `Workflow · ${title}`,
        `Current status · ${screen.state}`,
        `Next action · ${screen.action}`,
      ],
      action: screen.action,
    },
  }
}

